#!/usr/bin/env python3
"""Separate honest postcollection18 context; no producer/raw design mutation."""
import argparse,datetime,json,pathlib,subprocess,sys
from final_common import add_inputs,parent_chain,environment,frozen_bytes,LOCALE,save_new,bind_final_sources,check_prior62
from saved_envelope import digest,load

def main():
 p=argparse.ArgumentParser();add_inputs(p);p.add_argument('--out-dir',type=pathlib.Path,required=True);p.add_argument('--run-reader',action='store_true');a=p.parse_args();assert not a.out_dir.exists();parent_chain(a);env=environment(a,'locale18');bind_final_sources(env);originals={name:frozen_bytes(env,want) for name,want in LOCALE.items()};prior_paths={'API-ACCEPTED.json':a.api,'BROWSER37-ACCEPTED.json':a.prior37,'PRIOR44-ACCEPTED.json':a.prior44,'verified-release.json':a.verified};prior_hashes={n:digest(v) for n,v in prior_paths.items()};context={'context_kind':'POSTCOLLECTION_PARENT_REVIEW_NOT_PREISSUE_AUTHORIZATION','actual_context_created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'immutable_execution_design_sha256':env['execution_design_sha256'],'immutable_config_canonical_sha256':env['config_canonical_sha256'],'immutable_top_manifest_sha256':env['top_manifest_sha256'],'immutable_locale18_group_manifest_sha256':env['group_manifest_sha256'],'actual_external_issue_sha256':env['external_issue_sha256'],'genuine_parent37_receipt_sha256':digest(a.prior37),'genuine_parentPRIOR44_receipt_sha256':digest(a.prior44),'source':env['S'],'binding':env['binding'],'saved_reader_sha256':LOCALE['review-locale18-848.py'],'saved_predicates_sha256':LOCALE['locale18_saved_predicates.py'],'prior_acceptance_files_sha256':prior_hashes,'prior44_receipt_sha256':digest(a.prior44),'worker_sha256':env['worker_sha256'],'locale_helper_sha256':LOCALE['locale-controls.mjs'],'wrapper_sha256':LOCALE['run-locale18.mjs'],'producer_raw_or_design_modified':False}
 a.out_dir.mkdir(mode=0o700);prior_dir=a.out_dir/'prior-acceptance';prior_dir.mkdir(mode=0o700)
 for name,b in originals.items():(a.out_dir/name).write_bytes(b);assert digest(a.out_dir/name)==LOCALE[name]
 for name,path in prior_paths.items():(prior_dir/name).write_bytes(path.read_bytes());assert digest(prior_dir/name)==prior_hashes[name]
 save_new(a.out_dir/'postcollection-context.json',context)
 prepared={'state':'POSTCOLLECTION_CONTEXT_PREPARED_NOT_REVIEW_ACCEPTED','source':env['S'],'engine':env['binding']['engine'],'execution_design_sha256':env['execution_design_sha256'],'top_manifest_sha256':env['top_manifest_sha256'],'raw_group_manifest_sha256':env['group_manifest_sha256'],'context_sha256':digest(a.out_dir/'postcollection-context.json'),'original_reader_invoked':False,'producer_design_raw_modified':False,'browser_engine_provider_calls':0};save_new(a.out_dir/'CONTEXT-PREPARED.json',prepared)
 if a.run_reader:
  output=a.out_dir/'original-locale18-result.json';argv=[sys.executable,str(a.out_dir/'review-locale18-848.py'),'--evidence',str(env['e']),'--design',str(a.out_dir/'postcollection-context.json'),'--prior44',str(prior_dir/'PRIOR44-ACCEPTED.json'),'--out',str(output)]
  with (a.out_dir/'original-reader.stdout').open('xb') as out,(a.out_dir/'original-reader.stderr').open('xb') as err:run=subprocess.run(argv,stdout=out,stderr=err,check=False,timeout=300)
  save_new(a.out_dir/'ORIGINAL-READER-EXECUTION.json',{'kind':'SAVED_ONLY_EXACT_ORIGINAL_READER','reader_sha256':LOCALE['review-locale18-848.py'],'predicates_sha256':LOCALE['locale18_saved_predicates.py'],'exit_status':run.returncode,'stdout_sha256':digest(a.out_dir/'original-reader.stdout'),'stderr_sha256':digest(a.out_dir/'original-reader.stderr'),'report_sha256':digest(env['e']/'actual-browser/report.json'),'context_sha256':digest(a.out_dir/'postcollection-context.json'),'browser_engine_provider_calls':0})
  assert run.returncode==0 and output.is_file(),'Preserve original reader failure; no automatic retry/context/raw rewrite'
  actual=load(output);check_prior62(actual,source=env['S'],engine=env['binding']['engine'],locale_report_sha=digest(env['e']/'actual-browser/report.json'),locale_manifest_sha=env['group_manifest_sha256'],prior44_sha=digest(a.prior44))
  result={'state':'GROUPED_LOCALE18_SAVED_REVIEW_ACCEPTED','source':env['S'],'engine':env['binding']['engine'],'execution_design_sha256':env['execution_design_sha256'],'config_canonical_sha256':env['config_canonical_sha256'],'top_manifest_sha256':env['top_manifest_sha256'],'group_manifest_sha256':env['group_manifest_sha256'],'report_sha256':digest(env['e']/'actual-browser/report.json'),'original_reader_result_sha256':digest(output),'original_reader_sha256':LOCALE['review-locale18-848.py'],'original_predicates_sha256':LOCALE['locale18_saved_predicates.py'],'worker_sha256':env['worker_sha256'],'combined_worker_sha256':env['worker_sha256'],'external_issue_sha256':env['external_issue_sha256'],'verified_artifact_receipt_sha256':env['verified_sha256'],'api_acceptance_sha256':env['api_sha256'],'native_reference_sha256':env['native_reference_sha256'],'prior37_receipt_sha256':digest(a.prior37),'prior44_receipt_sha256':digest(a.prior44),'postcollection_context_sha256':digest(a.out_dir/'postcollection-context.json'),'retained62_accepted':True,'heat2_still_separately_required':True,'all64_accepted':False,'scientific_catalog_additions':0,'browser_engine_provider_calls':0};save_new(a.out_dir/'LOCALE18-REVIEW-ACCEPTED.json',result)
 for f in a.out_dir.rglob('*'):
  if f.is_file():f.chmod(0o600)
if __name__=='__main__':main()
